import{_ as a,c as e,o as d,b0 as o}from"./chunks/framework.C5ev1SXp.js";const r="/scm-docs/assets/tcp-udp.CUCjGkt7.svg",b=JSON.parse('{"title":"LV035-传输层端口UDP与TCP","description":null,"frontmatter":{"title":"LV035-传输层端口UDP与TCP","date":"2026-10-14T22:10:00.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/network-basics/126d628e1bb02d6a3f5e9c41","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-14T22:10:00.180Z","fulluuid":"2d6a3f5e9c414b18a8f02d3c7e615094","useduuid":"2d6a3f5e9"}},"headers":[],"relativePath":"sdoc/advanced-chapter/network-basics/126d628e1bb02d6a3f5e9c41.md","filePath":"sdoc/30-进阶篇/05-网络基础/LV035-传输层端口UDP与TCP.md","lastUpdated":1792231946000}'),c={name:"sdoc/advanced-chapter/network-basics/126d628e1bb02d6a3f5e9c41.md"};function n(l,t,s,i,h,p){return d(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="lv035-传输层端口udp与tcp" tabindex="-1">LV035-传输层端口UDP与TCP <a class="header-anchor" href="#lv035-传输层端口udp与tcp" aria-label="Permalink to &quot;LV035-传输层端口UDP与TCP&quot;">​</a></h1><h2 id="一、-为什么还需要传输层" tabindex="-1">一、 为什么还需要传输层 <a class="header-anchor" href="#一、-为什么还需要传输层" aria-label="Permalink to &quot;一、 为什么还需要传输层&quot;">​</a></h2><h3 id="_1-ip-只把包送到主机-不送到程序" tabindex="-1">1. IP 只把包送到主机，不送到程序 <a class="header-anchor" href="#_1-ip-只把包送到主机-不送到程序" aria-label="Permalink to &quot;1. IP 只把包送到主机，不送到程序&quot;">​</a></h3><p>前面几篇解决了&quot;怎么把包送到目标主机&quot;：IP 负责端到端寻址，MAC 负责一跳一跳搬运。但目标主机上同时跑着很多程序——浏览器、聊天软件、终端——<strong>包到了主机，应该交给谁？</strong></p><p>IP 层回答不了这个问题：它的头里只有主机地址，没有&quot;程序&quot;的概念。区分程序是传输层的工作。</p><h3 id="_2-端口-同一台主机上的分机号" tabindex="-1">2. 端口：同一台主机上的分机号 <a class="header-anchor" href="#_2-端口-同一台主机上的分机号" aria-label="Permalink to &quot;2. 端口：同一台主机上的分机号&quot;">​</a></h3><p>传输层给每个程序分配一个<strong>端口号</strong>（16 位，0 ~ 65535），整个寻址链条到这才完整：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MAC 找到下一跳的设备  →  IP 找到最终的主机  →  端口找到主机上的哪个程序</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>端口号的约定俗成分三段：</p><table tabindex="0"><thead><tr><th>范围</th><th>名称</th><th>典型用途</th></tr></thead><tbody><tr><td>0 ~ 1023</td><td>知名端口</td><td>80 = HTTP、53 = DNS、69 = TFTP、67/68 = DHCP</td></tr><tr><td>1024 ~ 49151</td><td>注册端口</td><td>各种约定好的服务</td></tr><tr><td>49152 ~ 65535</td><td>动态端口</td><td>客户端临时使用，用完即弃</td></tr></tbody></table><p>注意<strong>知名端口绑定的是服务端</strong>：客户端发请求时，目的端口是服务器的知名端口，源端口则是一个临时选的动态端口。所以抓包看方向，看端口就能分清。</p><h3 id="_3-本工程用到的端口" tabindex="-1">3. 本工程用到的端口 <a class="header-anchor" href="#_3-本工程用到的端口" aria-label="Permalink to &quot;3. 本工程用到的端口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>端口</th><th>谁在用</th><th>协议</th><th>出处</th></tr></thead><tbody><tr><td>8888</td><td>板子的 TCP 升级服务器</td><td>TCP</td><td><a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5205f2a80bf1e.html">LV020-网络通信实验</a> 第三节</td></tr><tr><td>69</td><td>PC 侧的 TFTP 服务器</td><td>UDP</td><td><a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5261051823e07.html">LV025-基于TFTP的网络升级实验</a></td></tr><tr><td>67 / 68</td><td>DHCP 服务器 / 客户端</td><td>UDP</td><td><a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0326cce94ffc3.html">LV040-DHCP与IP地址自动获取</a> 第二节</td></tr></tbody></table><h2 id="二、-udp-无连接的信封" tabindex="-1">二、 UDP：无连接的信封 <a class="header-anchor" href="#二、-udp-无连接的信封" aria-label="Permalink to &quot;二、 UDP：无连接的信封&quot;">​</a></h2><h3 id="_1-udp-头只有-8-字节" tabindex="-1">1. UDP 头只有 8 字节 <a class="header-anchor" href="#_1-udp-头只有-8-字节" aria-label="Permalink to &quot;1. UDP 头只有 8 字节&quot;">​</a></h3><p>UDP（用户数据报协议）是传输层里最薄的协议，头部固定 8 字节：</p><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>说明</th></tr></thead><tbody><tr><td>源端口</td><td>2 字节</td><td>发送方端口</td></tr><tr><td>目的端口</td><td>2 字节</td><td>接收方端口</td></tr><tr><td>长度</td><td>2 字节</td><td>头 + 数据的总长度</td></tr><tr><td>校验和</td><td>2 字节</td><td>覆盖头与数据</td></tr></tbody></table><p>没有序号、没有连接状态、没有窗口。<strong>发个 UDP 包就像寄一封信</strong>：写好地址扔进邮筒，之后就不管了。</p><h3 id="_2-三个-不保证" tabindex="-1">2. 三个&quot;不保证&quot; <a class="header-anchor" href="#_2-三个-不保证" aria-label="Permalink to &quot;2. 三个&quot;不保证&quot;&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>含义</th><th>后果</th></tr></thead><tbody><tr><td>不保证送达</td><td>丢了就丢了，没人重传</td><td>可靠性要靠应用自己解决</td></tr><tr><td>不保证顺序</td><td>后发的可能先到</td><td>应用要自己编号或容忍乱序</td></tr><tr><td>按报文交付</td><td>收发的单位是&quot;一个包&quot;，边界保留</td><td>发两次 512 字节，收到的一定是两包</td></tr></tbody></table><p>第三条是 UDP 与 TCP 最本质的区别：<strong>UDP 保留报文边界</strong>。发一个 512 字节的 UDP 报文，对方一次性收到的就是这个 512 字节，不会和下一个包粘在一起。</p><h3 id="_3-什么场景适合-udp" tabindex="-1">3. 什么场景适合 UDP <a class="header-anchor" href="#_3-什么场景适合-udp" aria-label="Permalink to &quot;3. 什么场景适合 UDP&quot;">​</a></h3><ul><li><strong>一问一答的小交互</strong>：DNS 查询、DHCP 地址申请。一个包问、一个包答，不值得先建连接。</li><li><strong>允许丢包的实时流</strong>：音视频、在线游戏。等重传还不如要新数据。</li><li><strong>链路足够可靠的局域网</strong>：丢包率本来就近乎零，可靠性的成本付得不值。</li></ul><p>TFTP 选 UDP 就属于第一种和第三种的组合，见第五节。</p><h2 id="三、-tcp-有连接的字节流" tabindex="-1">三、 TCP：有连接的字节流 <a class="header-anchor" href="#三、-tcp-有连接的字节流" aria-label="Permalink to &quot;三、 TCP：有连接的字节流&quot;">​</a></h2><h3 id="_1-字节流与报文的区别" tabindex="-1">1. 字节流与报文的区别 <a class="header-anchor" href="#_1-字节流与报文的区别" aria-label="Permalink to &quot;1. 字节流与报文的区别&quot;">​</a></h3><p>TCP（传输控制协议）与 UDP 的世界观完全不同：<strong>它传输的是一条没有边界的字节流。</strong></p><p>应用程序调三次 <code>send(512)</code>，TCP 可能把它合成一个 1536 字节的段发出去，也可能切成六个 256 字节的小段；接收方读出来的只是&quot;一串顺序正确的字节&quot;，至于这串字节是几次 <code>send</code> 凑出来的，接收方根本不知道。</p><p>这意味着<strong>应用层的&quot;消息边界&quot;必须自己定</strong>。本工程的做法就是 <code>IAPBIN01</code> 帧：用魔数定位起点、用长度字段声明边界——这正是 TCP 字节流上&quot;自己定义协议&quot;的典型做法（帧格式见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a52a7c8f19d4b3.html">LV030-网络升级帧协议与三条通道</a> 第二节）。</p><h3 id="_2-三次握手与四次挥手" tabindex="-1">2. 三次握手与四次挥手 <a class="header-anchor" href="#_2-三次握手与四次挥手" aria-label="Permalink to &quot;2. 三次握手与四次挥手&quot;">​</a></h3><p>TCP 通信前先<strong>建立连接</strong>，握手只需要三个包：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端                服务端</span></span>
<span class="line"><span>  │──── SYN ────────────▶│   &quot;我要连你，我的起始序号是 X&quot;</span></span>
<span class="line"><span>  │◀─── SYN + ACK ───────│   &quot;好，我的起始序号是 Y，你的 X 收到&quot;</span></span>
<span class="line"><span>  │──── ACK ────────────▶│   &quot;你的 Y 收到，连接建立&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>结束时因为双方要各自宣布&quot;我不再发了&quot;，需要四个包（FIN → ACK → FIN → ACK）。</p><p>三次握手的目的不复杂：<strong>双方确认对方的存在，并交换各自的初始序号</strong>。它要证明&quot;我能发给你、你也能发给我&quot;，两个包证明不了双向都通，所以是三个。</p><h3 id="_3-序号、ack-与重传" tabindex="-1">3. 序号、ACK 与重传 <a class="header-anchor" href="#_3-序号、ack-与重传" aria-label="Permalink to &quot;3. 序号、ACK 与重传&quot;">​</a></h3><p>连接建立后，可靠传输靠三个机制：</p><p>（1）<strong>序号</strong>：字节流里每个字节都有编号。报文段头里的序号就是&quot;我这段数据的第一个字节是第几号&quot;。</p><p>（2）<strong>ACK</strong>：接收方收到数据后回 ACK，告诉对方&quot;第 N 号之前的字节我都收到了&quot;。</p><p>（3）<strong>超时重传</strong>：发送方发出数据后启动定时器，超时没收到 ACK 就重发。</p><p>乱序到达的段先缓存起来，按序号排好再交给上层。<strong>对应用来说，TCP 呈现的就是一条不丢、不乱、不重复的字节流</strong>——代价是头更大（20 字节起）、状态机更复杂、内存占用更高。</p><h3 id="_4-滑动窗口与-mss" tabindex="-1">4. 滑动窗口与 MSS <a class="header-anchor" href="#_4-滑动窗口与-mss" aria-label="Permalink to &quot;4. 滑动窗口与 MSS&quot;">​</a></h3><p>两个决定传输效率的参数：</p><table tabindex="0"><thead><tr><th>参数</th><th>含义</th><th>本工程的取值</th></tr></thead><tbody><tr><td>接收窗口（RWND）</td><td>接收方允许对方&quot;最多未确认多少字节&quot;</td><td><code>TCP_WND = 4 × MSS</code> = 2144 字节</td></tr><tr><td>最大报文段（MSS）</td><td>一个段最多装多少数据，握手时各自宣布</td><td><code>TCP_MSS = 536</code>（lwIP 默认值）</td></tr></tbody></table><p>滑动窗口的作用类比&quot;发票报销&quot;：发出去的段相当于垫出去的钱，窗口就是&quot;最多能垫多少&quot;——垫满之前不必等报销回来，所以链路能跑满。</p><p>MSS 的细节（为什么是 536 而不是 1460、对分段数量的影响）见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a51d3a6f2be804.html">LV015-lwIP配置与初始化</a> 第二节。</p><img src="`+r+'" alt="TCP 三次握手与 UDP 一问一答的对比"><h2 id="四、-udp-与-tcp-的对照" tabindex="-1">四、 UDP 与 TCP 的对照 <a class="header-anchor" href="#四、-udp-与-tcp-的对照" aria-label="Permalink to &quot;四、 UDP 与 TCP 的对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>UDP</th><th>TCP</th></tr></thead><tbody><tr><td>连接</td><td>无连接</td><td>先握手建连接</td></tr><tr><td>传输单位</td><td>报文（保留边界）</td><td>字节流（无边界）</td></tr><tr><td>可靠性</td><td>不保证送达、不保证顺序</td><td>不丢、不乱、不重复</td></tr><tr><td>头部长度</td><td>固定 8 字节</td><td>20 字节起</td></tr><tr><td>状态开销</td><td>无</td><td>每个连接一个控制块（<code>tcp_pcb</code>）</td></tr><tr><td>本工程用法</td><td>TFTP（69）、DHCP（67/68）</td><td>升级通道（8888）</td></tr></tbody></table><p>选择标准就一句话：<strong>宁可自己处理丢包也要省掉连接开销，选 UDP；字节序不能错、丢了必须补上，选 TCP。</strong></p><h2 id="五、-在本工程里的落地" tabindex="-1">五、 在本工程里的落地 <a class="header-anchor" href="#五、-在本工程里的落地" aria-label="Permalink to &quot;五、 在本工程里的落地&quot;">​</a></h2><h3 id="_1-tftp-为什么用-udp" tabindex="-1">1. TFTP 为什么用 UDP <a class="header-anchor" href="#_1-tftp-为什么用-udp" aria-label="Permalink to &quot;1. TFTP 为什么用 UDP&quot;">​</a></h3><p>TFTP 是&quot;一问一答的小交互&quot;的极端形态：每块 512 字节，收到一块回一个 ACK，服务器没收到 ACK 就重发。<strong>可靠性由协议自己在应用层实现了</strong>，所以不需要 TCP 再保证一遍——再用 TCP 就是两套重传互相打架。</p><p>而且 UDP 无连接的特性让&quot;服务器收到 RRQ 后换一个端口（TID）回数据&quot;这种玩法成为可能，这在 TCP 的固定四元组连接里是做不了的（细节见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5261051823e07.html">LV025</a> 第五节）。</p><h3 id="_2-升级通道为什么用-tcp" tabindex="-1">2. 升级通道为什么用 TCP <a class="header-anchor" href="#_2-升级通道为什么用-tcp" aria-label="Permalink to &quot;2. 升级通道为什么用 TCP&quot;">​</a></h3><p>反过来，升级通道传的是&quot;不允许错一个字节&quot;的固件，而且 PC 侧要写脚本——TCP 的字节流语义让脚本只需要 <code>sendall()</code> 了事，重传、排序、流量控制全部由协议栈兜底。</p><p>板侧为此付出的代价是一个 <code>tcp_pcb</code> 控制块（<code>MEMP_NUM_TCP_PCB = 5</code>）以及回调式编程的复杂度，这在 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a51b6ce0b937cd.html">LV010-lwIP协议栈移植</a> 里已经讲过。</p><h3 id="_3-ping-为什么用不上传输层" tabindex="-1">3. ping 为什么用不上传输层 <a class="header-anchor" href="#_3-ping-为什么用不上传输层" aria-label="Permalink to &quot;3. ping 为什么用不上传输层&quot;">​</a></h3><p>ping 用的是 <strong>ICMP</strong>，它直接坐在 IP 层上（协议号 1），<strong>根本没有端口</strong>。所以：</p><ul><li>&quot;板子的 8888 端口被防火墙拦了&quot;这类说法对 ping 不成立——防火墙拦不拦 ICMP 是另一组规则；</li><li>ping 通不代表 TCP 能连上，两者验证的是不同的层。</li></ul><p>这就是为什么排错要&quot;先 ping、再 nc&quot;：ping 通了说明网络层以下都好，再往上才是端口的事（工具用法见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0347a8c2e0d9b.html">LV045-网络调试工具与抓包</a>）。</p><h3 id="_4-lwip-里的对应文件" tabindex="-1">4. lwIP 里的对应文件 <a class="header-anchor" href="#_4-lwip-里的对应文件" aria-label="Permalink to &quot;4. lwIP 里的对应文件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>协议</th><th>内核文件</th><th>本工程的应用</th></tr></thead><tbody><tr><td>TCP</td><td><code>src/core/tcp.c</code>、<code>tcp_in.c</code>、<code>tcp_out.c</code></td><td><code>port/iap_tcp.c</code>（8888 端口服务器）</td></tr><tr><td>UDP</td><td><code>src/core/udp.c</code></td><td><code>Drivers/BSP/Ota/ota_tftp.c</code>（TFTP 客户端）</td></tr><tr><td>ICMP</td><td><code>src/core/ipv4/icmp.c</code></td><td>无应用代码，协议栈自动应答</td></tr></tbody></table><p>lwIP 提供的是 <strong>RAW API</strong>：没有 socket、没有 <code>read/write</code>，所有收发都是回调（<code>tcp_accept</code>、<code>tcp_recv</code>、<code>udp_recv</code>）。回调运行在主循环上下文，所以<a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a51b6ce0b937cd.html">移植那篇</a>的硬约束&quot;回调里只做 O(1) 搬运&quot;在 UDP 与 TCP 上同样成立。</p><h2 id="六、-小结与参考资料" tabindex="-1">六、 小结与参考资料 <a class="header-anchor" href="#六、-小结与参考资料" aria-label="Permalink to &quot;六、 小结与参考资料&quot;">​</a></h2><h3 id="_1-本篇小结" tabindex="-1">1. 本篇小结 <a class="header-anchor" href="#_1-本篇小结" aria-label="Permalink to &quot;1. 本篇小结&quot;">​</a></h3><ul><li>IP 把包送到主机，端口把包送到程序；寻址链是 MAC → IP → 端口。</li><li>知名端口绑服务端（80、53、69、67/68），客户端用动态端口；看端口就能分清抓包方向。</li><li>UDP 是无连接的&quot;信封&quot;：8 字节头、不保证送达与顺序、保留报文边界，适合小交互与可靠链路。</li><li>TCP 是有连接的&quot;字节流&quot;：三次握手交换初始序号，靠序号 + ACK + 超时重传保证不丢不乱，靠滑动窗口跑满链路；应用层消息边界要自己定。</li><li>本工程的选型：TFTP 用 UDP（应用层自己做停等重传），升级通道用 TCP（字节流 + 协议栈兜底可靠性），ping 用 ICMP（根本不到传输层）。</li><li>lwIP 只有 RAW API，收发全部走回调；<code>tcp_pcb</code> 数量受 <code>MEMP_NUM_TCP_PCB = 5</code> 限制。</li></ul><h3 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h3><ul><li>TCP 实现：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/src/core/tcp.c" target="_blank" rel="noreferrer"><code>tcp.c</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/src/core/tcp_in.c" target="_blank" rel="noreferrer"><code>tcp_in.c</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/src/core/tcp_out.c" target="_blank" rel="noreferrer"><code>tcp_out.c</code></a></li><li>UDP 实现：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/src/core/udp.c" target="_blank" rel="noreferrer"><code>udp.c</code></a></li><li>本工程应用：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/port/iap_tcp.c" target="_blank" rel="noreferrer"><code>iap_tcp.c</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Drivers/BSP/Ota/ota_tftp.c" target="_blank" rel="noreferrer"><code>ota_tftp.c</code></a></li><li>手册：<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/10-lwIP/STM32F1%20LWIP%E5%BC%80%E5%8F%91%E6%89%8B%E5%86%8C%28DM9000%E7%89%88%29_V1.1.pdf" target="_blank" rel="noreferrer"><code>STM32F1 LWIP开发手册(DM9000版)_V1.1.pdf</code></a> 第三章 UDP、第五章 TCP</li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',70)])])}const P=a(c,[["render",n]]);export{b as __pageData,P as default};
